using System;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;

namespace CodexAutoProxyRepair {
 public sealed class VerificationReport { public string Summary {get;set;} public string Details {get;set;} public string CodexState {get;set;} public string DotsState {get;set;} public int RecentRetryCount {get;set;} }
 public static class ServiceVerification {
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_open_v2(byte[] file,out IntPtr db,int flags,IntPtr vfs);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_busy_timeout(IntPtr db,int ms);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_prepare_v2(IntPtr db,byte[] sql,int n,out IntPtr stmt,IntPtr tail);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_bind_int64(IntPtr stmt,int index,long value);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_step(IntPtr stmt);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_column_int(IntPtr stmt,int col);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_finalize(IntPtr stmt);
  [DefaultDllImportSearchPaths(DllImportSearchPath.System32)] [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_close_v2(IntPtr db);
  static byte[] Utf8(string s){return Encoding.UTF8.GetBytes(s+"\0");}
  static int RetryCount(DateTime since){IntPtr db=IntPtr.Zero,stmt=IntPtr.Zero;try{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),@".codex\logs_2.sqlite");if(!File.Exists(path))return -1;if(sqlite3_open_v2(Utf8(path),out db,1,IntPtr.Zero)!=0)return -1;sqlite3_busy_timeout(db,300);string q="SELECT count(*) FROM logs WHERE ts >= ?1 AND target = 'codex_core::responses_retry' AND (level='WARN' OR level='ERROR')";if(sqlite3_prepare_v2(db,Utf8(q),-1,out stmt,IntPtr.Zero)!=0)return -1;long start=(long)(since.ToUniversalTime()-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;if(sqlite3_bind_int64(stmt,1,start)!=0||sqlite3_step(stmt)!=100)return -1;return sqlite3_column_int(stmt,0);}catch{return -1;}finally{if(stmt!=IntPtr.Zero)sqlite3_finalize(stmt);if(db!=IntPtr.Zero)sqlite3_close_v2(db);}}
  static DateTime? Started(out int pid){pid=0;DateTime? earliest=null;foreach(var p in Process.GetProcessesByName("ChatGPT").Concat(Process.GetProcessesByName("Codex"))){try{string file=p.MainModule.FileName;if(file.IndexOf(@"\OpenAI.Codex_",StringComparison.OrdinalIgnoreCase)<0)continue;DateTime t=p.StartTime.ToUniversalTime();if(!earliest.HasValue||t<earliest.Value){earliest=t;pid=p.Id;}}catch{}finally{p.Dispose();}}return earliest;}
  static string Dots(DateTime since,int pid){try{string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Packages\OpenAI.Codex_2p2nqsd0c76g0\LocalCache\Local\Codex\Logs");string[] dates={DateTime.Now.ToString(@"yyyy\MM\dd"),DateTime.Now.AddDays(-1).ToString(@"yyyy\MM\dd")};DateTime newest=DateTime.MinValue;string state=null;foreach(string date in dates){string folder=Path.Combine(root,date);if(!Directory.Exists(folder))continue;foreach(string file in Directory.GetFiles(folder,"codex-desktop-*.log").OrderByDescending(f=>File.GetLastWriteTimeUtc(f)).Take(8)){if(File.GetLastWriteTimeUtc(file)<since || Path.GetFileName(file).IndexOf("-"+pid+"-t",StringComparison.OrdinalIgnoreCase)<0)continue;using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){long offset=Math.Max(0,stream.Length-2*1024*1024);stream.Seek(offset,SeekOrigin.Begin);using(var reader=new StreamReader(stream,Encoding.UTF8)){if(offset>0)reader.ReadLine();string line;while((line=reader.ReadLine())!=null){if(line.Length<24||line.IndexOf("rendezvous",StringComparison.OrdinalIgnoreCase)<0)continue;DateTime when;if(!DateTime.TryParse(line.Substring(0,24),CultureInfo.InvariantCulture,DateTimeStyles.AdjustToUniversal|DateTimeStyles.AssumeUniversal,out when)||when<since||when<newest)continue;bool failed=line.IndexOf("failed",StringComparison.OrdinalIgnoreCase)>=0||line.IndexOf("disconnected",StringComparison.OrdinalIgnoreCase)>=0;bool connected=line.IndexOf("connected to rendezvous",StringComparison.OrdinalIgnoreCase)>=0;if(!failed&&!connected)continue;newest=when;state=failed?"启动后观察到握手失败":"已观察到启动后设备握手";}}}}}return state??"未观察到握手信号，待验证";}catch{return "握手状态未知（无法读取）";}}
  internal static DateTime RetrySince(DateTime start,DateTime now){DateTime recent=now.AddMinutes(-5);return start>recent?start:recent;}
  internal static bool IsTerminalDots(string state){return state=="已观察到启动后设备握手" || state=="启动后观察到握手失败";}
  public static VerificationReport WaitForSignals(){DateTime until=DateTime.UtcNow.AddSeconds(45);VerificationReport r;do{r=Run();if(IsTerminalDots(r.DotsState))return r;TimeSpan remaining=until-DateTime.UtcNow;if(remaining.TotalMilliseconds<=0)return r;System.Threading.Thread.Sleep(Math.Max(1,Math.Min(2500,(int)remaining.TotalMilliseconds)));}while(true);}
  public static VerificationReport Run(){var r=new VerificationReport{RecentRetryCount=-1};int pid;var start=Started(out pid);if(!start.HasValue){r.CodexState="未运行或进程信息不可读，待验证";r.DotsState="未运行或进程信息不可读，待验证";r.Summary="尚无法复检服务";r.Details="请启动 Codex 后复检；若进程信息不可读，请检查权限。";return r;}DateTime retrySince=RetrySince(start.Value,DateTime.UtcNow);r.RecentRetryCount=RetryCount(retrySince);r.CodexState=r.RecentRetryCount<0?"超时状态未知，待真实消息确认":r.RecentRetryCount>0?"近5分钟内有重试，待检查":"近5分钟未发现重试，仍需真实消息确认";r.DotsState=Dots(start.Value,pid);r.Summary="已启动；复检结果需结合实际使用确认";r.Details="重试数量统计近5分钟且不早于当前客户端启动，为本机汇总，可能包含其他会话；未验证某条消息成功。代理 TCP 连接不代表服务恢复。请发送实际消息，并在 Dots 设备列表确认状态。";return r;}
 }
 public sealed class CompatibilityReport {public string Summary {get;set;} public string Details {get;set;}}
 public static class Compatibility {
  internal static string RunProbe(string ps,string args){var info=new ProcessStartInfo(ps,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};using(var p=Process.Start(info)){var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(20000)){try{p.Kill();p.WaitForExit(2000);}catch{}return null;}if(!stdout.Wait(2000)||!stderr.Wait(2000)||p.ExitCode!=0)return null;return stdout.Result.Trim();}}
  static string AppxAndManifest(string ps){try{string script="$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='Stop'; if(!(Get-Command Get-AppxPackage -ErrorAction SilentlyContinue) -or !(Get-Command Get-AppxPackageManifest -ErrorAction SilentlyContinue)){Write-Output 'NO_APPX';exit}; $p=Get-AppxPackage -Name 'OpenAI.Codex' | Where-Object {$_.PackageFamilyName -ceq 'OpenAI.Codex_2p2nqsd0c76g0' -and $_.SignatureKind -eq 'Store' -and !$_.IsDevelopmentMode -and $_.Status -eq 'Ok'} | Sort-Object {[version]$_.Version} -Descending | Select-Object -First 1; if(!$p){Write-Output 'NO_PACKAGE';exit};$m=Get-AppxPackageManifest $p;$a=@($m.Package.Applications.Application | Where-Object {$_.Id -eq 'App'})[0];if(!$a -or !$a.Executable){Write-Output 'UNKNOWN';exit};$rel=[string]$a.Executable;$root=[IO.Path]::GetFullPath($p.InstallLocation).TrimEnd('\')+'\';if([IO.Path]::IsPathRooted($rel) -or [IO.Path]::GetFileName($rel) -notin @('ChatGPT.exe','Codex.exe')){Write-Output 'UNKNOWN';exit};$exe=[IO.Path]::GetFullPath((Join-Path $root $rel));if($exe.StartsWith($root,[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $exe -PathType Leaf)){Write-Output 'OK'}else{Write-Output 'UNKNOWN'}";string args="-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script));string value=RunProbe(ps,args);switch(value){case "OK":return "Appx 命令及官方清单启动路径可识别";case "NO_APPX":return "缺少 Appx 命令";case "NO_PACKAGE":return "未找到受支持的官方包";default:return "Appx 或官方清单状态未知";}}catch{return "Appx 或官方清单状态未知";}}
  public static CompatibilityReport Check(){var r=new CompatibilityReport();string proxy;try{ProxyConfig.Read();proxy="手动代理可读取";}catch(Exception e){proxy=e.Message;}string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");bool exists=File.Exists(ps);string power=exists?"Windows PowerShell 可用":"缺少 Windows PowerShell";string app=exists?MainForm.DetectInstall():"安装状态未知";string manifest=exists?AppxAndManifest(ps):"Appx 状态未知";r.Summary=power+"；"+proxy;r.Details="Windows "+Environment.OSVersion.Version+"；"+(Environment.Is64BitOperatingSystem?"64 位":"32 位")+"；"+app+"；"+manifest+"。进程或日志不可读时结果为未知。";return r;}
 }
}
